"""Render the reviewed evidence into a standalone printable HTML report."""
import html
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
E = json.loads((HERE/'evidence.json').read_text())
TS = E['trials']
esc = html.escape
PIN = '2b65a811b1d154a0c6932037f4ab74382d7b4cb4'
GH = 'https://github.com/burggraf/supa-desktop/blob/'+PIN+'/'

def link(url, label):
    return '<a href="'+esc(url,quote=True)+'">'+esc(label)+'</a>'

def source(path,label,lines=''):
    return link(GH+path+lines,label)

def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def metric(t,name):
    vals=[v['observedDelta'] for v in t['projectDatabaseSeries'].values() if v['name']==name]
    return vals[0] if len(vals)==1 else None

def chart():
    svg=['<svg role="img" aria-label="Public feed and like p95 response time by concurrent users; latency rises sharply between 500 and 625 users" viewBox="0 0 700 285" style="width:100%;height:285px;font-family:inherit">']
    for sec in [0,2,4,6,8]:
        x=105+sec*65
        svg.append(f'<path d="M{x} 28V248" stroke="var(--border,#d6dce5)"/><text x="{x}" y="270" text-anchor="middle" fill="var(--muted-foreground,#617085)" font-size="12">{sec}s</text>')
    for x,color,label in [(105,'var(--chart-1,#2789d7)','Public feed'),(270,'var(--chart-2,#b264de)','Like')]:
        svg.append(f'<rect x="{x}" y="3" width="12" height="12" rx="2" fill="{color}"/><text x="{x+19}" y="14" fill="var(--foreground,#172b43)" font-size="12">{label}</text>')
    for i,t in enumerate(TS):
        y=46+i*54
        r=t['result'];svg.append(f'<text x="90" y="{y+15}" text-anchor="end" fill="var(--foreground,#172b43)" font-size="13">{t["users"]:,} users</text>')
        for j,(a,col) in enumerate([('listPublic','var(--chart-1,#2789d7)'),('like','var(--chart-2,#b264de)')]):
            val=r['perActionP95Ms'][a]/1000
            svg.append(f'<rect x="105" y="{y+j*18}" width="{max(2,val*65):.2f}" height="13" rx="2" fill="{col}"><title>{t["users"]} users: {a} p95 {val:.3f}s</title></rect><text x="{113+val*65:.2f}" y="{y+j*18+11}" fill="var(--foreground,#172b43)" font-size="11">{val:.2f}s</text>')
    svg.append('</svg>')
    return ''.join(svg)

chart_css='''html,body{margin:0;background:transparent;color:var(--foreground,#172b43);font-family:var(--font-sans,system-ui,sans-serif)}*{box-sizing:border-box}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:right;padding:9px 7px;border-bottom:1px solid var(--border,#d6dce5);white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:var(--muted-foreground,#617085);font-weight:500}p{line-height:1.55;font-size:14px}small{color:var(--muted-foreground,#617085);line-height:1.5}'''
chart_table=table(['Users','Result','Action errors','Mean active / 256'],[[f'{t["users"]:,}', 'Pass' if t['users']==500 else 'Latency failure' if t['users']==625 else 'Latency + errors',f'{t["result"]["actionFailurePercent"]:.2f}%',f'{t["result"]["gateway"]["activeRequests"]["mean"]:.1f}'] for t in TS])
chart_body=chart()+chart_table+'<p>500 passed this short run. At 625, latency failed despite only five gateway rejections. The exact sustainable limit is still unproven.</p><small>Native Supa Desktop 0.14.1 · M1 Max · 120-second measurement · read p95 target 0.50s; write p95 target 0.75s.</small>'
(HERE/'capacity-chart.html').write_text('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+chart_css+'</style></head><body>'+chart_body+'</body></html>')

content=[]
def add(s):content.append(s)
add('<p class="eyebrow">Performance investigation • 18 November 2026 • Supa Desktop 0.14.1</p><h1>Why capacity drops above 500 users</h1>')
add('''<p class="lead">The immediate 503 source is confirmed: the gateway exhausts its <strong>256 active-request permits</strong>. The deeper problem appears earlier: at 625 users, requests already take several seconds even though almost none are rejected. The strongest next step is to locate time spent inside the runtime and database connection path, then tune that bottleneck.</p>
<div class="callout"><strong>Observed boundary: 500 passed; 625 failed.</strong> These are individual short runs, not a certified sustainable capacity or an exact maximum. No configuration changes or new load runs were made for this analysis.</div>''')
add('<h2>1. What the four runs show</h2>'+chart())
add(table(['Concurrent users','Actions / failed','Action error %','Feed p95','Like p95','Successful actions/s'],[[f'{t["users"]:,}',f'{t["result"]["actions"]:,} / {t["result"]["failedActions"]:,}',f'{t["result"]["actionFailurePercent"]:.3f}%',f'{t["result"]["perActionP95Ms"]["listPublic"]/1000:.3f}s',f'{t["result"]["perActionP95Ms"]["like"]/1000:.3f}s',f'{t["successfulActionsPerSecond"]:.2f}'] for t in TS]))
add('''<p>At 625, all seven action types fail latency targets; the 0.272% action error rate remains below the 1% threshold. Reads have p95 between 4.72 and 5.00 seconds; writes range from 4.93 to 7.65 seconds. Read p95 must be below 500 ms, write p95 below 750 ms, and p99 below 2 seconds. At 750 and 1,000 both latency and errors fail.</p>
<p>Adding 25% more users from 500 to 625 reduces successful action throughput by 22%. At heavier load, fast rejected requests alter the action mix and reported latency distribution. The smaller like p95 at 1,000 is therefore not evidence of recovery; its action error rate is nearly 40%.</p>''')
add('<h2>2. Which component produces the 503s?</h2>')
add(table(['Users','Measured HTTP 503','Measured timeouts','All-phase request rejects','Upstream rejects','Captured 503 bodies'],[[t['users'],t['phaseHttpStatusCounts'].get('measurement:503',0),t['phaseHttpStatusCounts'].get('measurement:0',0),f'{t["gateway"]["counterDeltas"]["admission_rejections_total"]:,}',t['gateway']['counterDeltas']['upstream_admission_rejections_total'],t['gateway']['responseBodies']['captured']] for t in TS]))
add('''<p>All captured 503 bodies identify <code>{"error":"gateway_request_capacity"}</code>. At 625 all five 503s were captured; at 750 and 1,000 body logging was bounded to two samples per virtual user. No sampled body identified <code>gateway_upstream_capacity</code>. At every point, the all-phase HTTP 503 total equals the gateway admission-rejection counter delta. All-phase totals include preparation, ramp, warmup, measurement and sign-out; they must not be compared directly with measurement-only totals.</p>''')
add('<p>The release source waits up to 100 ms for an active-work permit, then returns that named 503. The permit remains held through response-body completion. Observed 503s average about 101–102 ms, matching this path. '+source('crates/core/src/gateway.rs','Gateway admission and response-body permit','#L667')+'</p>')
add(table(['Users','Active requests mean / peak','Upstream sockets peak','Inbound sockets peak','Gateway open FDs peak','Host CPU busy mean'],[[t['users'],f'{t["result"]["gateway"]["activeRequests"]["mean"]:.1f} / {t["result"]["gateway"]["activeRequests"]["maximum"]}',t['result']['gateway']['upstreamConnections']['maximum'],t['result']['gateway']['inboundConnections']['maximum'],t['result']['gateway']['openDescriptors']['maximum'],f'{100-t["result"]["hostCpu"]["idlePercent"]["mean"]:.1f}%'] for t in TS]))
add('''<p>The effective limits were 256 active requests, 2,048 inbound connections and a separate 2,048 upstream-connection budget. Gateway descriptor soft limit was 10,496; hard limit was reported as 9,223,372,036,854,775,807 (unlimited). Peak sampled gateway use was 1,305 descriptors, leaving 87.6% headroom. At 1,000, active requests equalled 256 in every timed sample. IPv4 and IPv6 API health checks succeeded after each load run. This is overload admission, with no evidence of the older listener failure or descriptor exhaustion.</p>
<p><strong>Raising the request limit alone does not address the observed latency failure:</strong> 625 already fails with only five rejections. It may permit a larger backlog and more client timeouts unless service throughput improves.</p>''')
add('<h2>3. Where the time goes</h2>')
add(table(['Users','Successful HTTP count','Mean duration','Mean first-byte wait','Mean receive','Successful HTTP/s'],[[t['users'],f'{t["rawHttp"]["2xx"]["http_req_duration"]["count"]:,}',f'{t["rawHttp"]["2xx"]["http_req_duration"]["mean"]:.2f} ms',f'{t["rawHttp"]["2xx"]["http_req_waiting"]["mean"]:.2f} ms',f'{t["rawHttp"]["2xx"]["http_req_receiving"]["mean"]:.3f} ms',f'{t["successfulHttpCompletedPerSecond"]:.2f}'] for t in TS]))
add('''<p>Over 99.9% of mean successful HTTP duration is first-byte waiting. Mean client connection setup is below 0.01 ms; mean response-body receive time remains below 0.05 ms. This localizes the symptom to the gateway/upstream processing path rather than TCP setup or downloading the body. It does not separate runtime queueing, pool acquisition, SQL, commit, or response preparation.</p>
<p>Timeouts last approximately 10 seconds. A logical action can issue multiple HTTP requests, so action durations and error counts differ from HTTP metrics. HTTP tables use <code>request_phase=measurement</code> and include requests that finish after the window boundary; action tables use the benchmark's original action accounting.</p>
<p>At 625, the mean occupancy of 240 requests is consistent in magnitude with roughly 151 successful HTTP requests/s taking 1.57 seconds each. This is a queueing consistency check, not a proof of which internal stage is slow. At 500, successful HTTP p95 rises from 26 ms in the first complete 10-second bucket to 377 ms in the last. Although the overall run passes, a longer repeat is essential to check whether latency stabilizes.</p>''')
add('<h2>4. Host and database evidence</h2>')
add(table(['Users','Backend mean CPU cores','Backend peak RSS¹','DB backends min–max / limit','PG cache hit²','Deadlocks / temp bytes'],[[t['users'],f'{t["result"]["backend"]["cpuCores"]["mean"]:.3f}',f'{t["result"]["backend"]["peakRssBytes"]/2**20:.1f} MiB',f'{t["result"]["database"]["databaseBackends"]["minimum"]}–{t["result"]["database"]["databaseBackends"]["maximum"]} / 60',f'{t["result"]["database"]["cacheHitFraction"]*100:.2f}%',f'{t["result"]["database"]["deadlockDelta"]} / {t["result"]["database"]["tempBytesDelta"]}'] for t in TS]))
add('''<p class="note">¹ Sum of sampled process RSS across gateway and both project runtimes/descendants; shared pages can be counted more than once. ² Delta hits / (hits + reads) in PostgreSQL shared buffers, excluding the OS file cache.</p>
<p>The M1 Max has 10 cores and 64 GiB. Host CPU averages 23–27% busy, backend processes together average below one core, and the generator CPU pressure guard never fires. At 1,000 users, the benchmark runtime averages 0.628 cores, its PostgreSQL descendant 0.092, and the gateway 0.187. Memory pressure is reported as 1 (normal), with zero sampled swap usage. High macOS “used memory” alone is not evidence of memory pressure. These readings show host-wide headroom, while leaving open a bottleneck in a serial task, runtime worker, lock, pool or I/O path.</p>
<p>PostgreSQL has 6–7 backends against a configured maximum of 60. This rules out reaching that global connection ceiling in sampled data; it does not establish the effective PostgREST pool size or number of useful concurrent database operations. At 1,000, one active/I/O-wait connection appears in 60 of 119 project scrapes; idle-in-transaction/client-wait appears in 89, peaking at two. These are profiling leads, not proof of physical disk saturation, a leak, or deadlock. '''+link('https://www.postgresql.org/docs/17/monitoring-stats.html','PostgreSQL statistics and wait-event semantics')+'</p>')
add(table(['Users','WAL generated','Full-page images','Requested / timed checkpoints','DB I/O reads / writes','Recorded SQL execution Δ'],[[t['users'],f'{metric(t,"supa_desktop_database_wal_bytes_total")/2**20:.2f} MiB',f'{metric(t,"supa_desktop_database_wal_full_page_images_total"):,}',f'{metric(t,"supa_desktop_database_checkpoints_requested_total")} / {metric(t,"supa_desktop_database_checkpoints_timed_total")}',f'{metric(t,"supa_desktop_database_io_reads_total"):,} / {metric(t,"supa_desktop_database_io_writes_total"):,}',f'{metric(t,"supa_desktop_database_tracked_statement_execution_seconds"):.3f}s'] for t in TS]))
add('''<p>These deltas come from cached project collectors across approximately 118–120 seconds, not exact synchronized SQL snapshots. Read/write counts are database I/O operations, not measured physical disk bytes or time. All four windows contain one requested checkpoint and no timed checkpoint. Only the 750 window records completed-checkpoint timing increments (76.946 seconds write phase, 0.163 seconds sync); checkpoint write phase can include pacing and must not be treated as foreground stall time. Zero completed timing deltas elsewhere do not mean checkpoint work was absent.</p>
<p>The tracked SQL execution aggregate rises by only 2.2–2.9 seconds in each sampled window. A separate read-only post-campaign <code>pg_stat_statements</code> query shows the public-feed statement at 43,579 calls and 0.131 ms mean execution, own-post/count at 36,250 calls and 0.107 ms, and single-like insert at 19,700 calls and 0.150 ms. These cumulative values include fixture preparation and all runs; they are not per-load SQL latency distributions and do not cover every part of a transaction. Collector freshness advances during load. The contrast with seconds-long HTTP waits prioritizes tracing outside the recorded statement executor, while requiring confirmation of collector coverage and runtime clock semantics before any exact time attribution.</p>''')
add('<h2>5. Configuration and source findings</h2>')
add(table(['Observed setting','Value','Practical implication'],[
['shared_buffers','16 MiB','Small database cache; candidate for a controlled memory increase.'],
['effective_cache_size','4 GiB','Planner estimate; does not allocate cache.'],
['work_mem','4 MiB','No recorded temporary-file spill; low priority.'],
['max_wal_size / wal_buffers','64 MiB / 512 KiB','Small WAL budgets; test after measuring commit/checkpoint costs.'],
['fsync / synchronous_commit / full_page_writes','on / on / on','Preserve durability in all comparisons.'],
['track_io_timing / track_wal_io_timing','off / off','Current data cannot quantify database I/O wait duration.'],
['max_parallel_workers / per_gather','0 / 0','Runtime support must be established before enabling.']]))
add('<p>These are read-only settings observed after the campaign; there were no benchmark-time setting snapshots and no pending restarts. Current feed, own-post, primary-key, likes(user,post) unique, and likes(post) indexes already exist. “Add the missing feed/likes index” is not supported by the evidence. Saved '+link('database-settings.json','settings')+', '+link('database-indexes.json','index definitions')+' and '+link('database-statements.json','sanitized cumulative statements')+' accompany this report.</p>')
add('<p>The pinned release source exposes <code>SUPA_GATEWAY_REQUESTS</code> and <code>SUPA_GATEWAY_CONNECTIONS</code> startup overrides. With the observed descriptor budget, request overrides can increase above the default 256, up to the selected connection allowance; connection overrides cannot exceed the computed default 2,048. These are environment variables read at startup, not confirmed GUI settings, and setting one in a shell does not change an already-running macOS app. '+source('crates/core/src/resources.rs','Capacity calculation and override validation','#L86')+'</p>')
add('<p>The HTTP client’s <code>pool_idle_per_host=16</code> limits cached idle connections; it is not the active-request limit or PostgreSQL pool size. Its client mutex is held briefly to clone/select the client rather than across the upstream request. The inspected logging code already uses a background thread and bounded batching; a claim that every request synchronously writes SQLite on this release would be unsupported. '+source('crates/core/src/gateway_capacity.rs','HTTP pool implementation')+' · '+source('crates/core/src/logs.rs','Log writer implementation')+'</p>')
add('<h2>6. Recommended experiments, in priority order</h2>')
experiments=[
('1 — Locate the queue and validate baseline', 'Repeat 500 and 625 with the same instrumentation and restored logical fixture, then profile a bounded 625 run. Attach a request ID and monotonic timestamps for permit wait, upstream connect, runtime dispatch, PostgREST pool checkout, transaction begin, SQL execution, commit, response headers and body completion. Record stage histograms, in-flight work and runtime/thread CPU. Correlate with SQL backend PID, state and wait event. Measure statement counter coverage and wall-clock versus guest-clock behavior.', 'A stage accounts for the seconds-long first-byte wait. A paired 500 repeat determines whether drift or run order changes the baseline.'),
('2 — Runtime and SQL-pool concurrency', 'Expose the actual PostgREST database-pool configuration, checked-out count, queue length and acquisition time. If supported by this bundled WASM build, sweep pool sizes 2, 4, 8 and 16 one at a time, keeping max_connections=60 and headroom for auth, metrics and administration. If pool wait stays low, investigate WASM executor scheduling, blocking host calls and shared transaction/connection locks. Do not assume native PostgREST defaults apply to this bundle.', 'Successful throughput increases and first-byte p95 falls at 625 without more SQL contention, memory pressure or errors. Reverse any change that increases queueing.'),
('3 — Cancellation and overload behavior', 'Trace a 10-second client timeout through gateway, runtime and SQL. Ensure disconnects and deadline expiry cancel queued work and release permits/transactions. The gateway source has a 120-second upstream header timeout, so verify no abandoned work survives needlessly. After throughput improves, compare request caps 128, 256 and 512 in separate runs. Keep the 2,048 connection budget unchanged initially.', 'No continued SQL/runtime work from abandoned requests; no permit or idle-transaction accumulation. A larger cap counts as an improvement only if all original latency and error targets pass.'),
('4 — Database cache', 'After validating WASM shared-memory/address-space support, sweep shared_buffers from 16 MiB to 64, then 128 MiB; consider 256 MiB only if needed. Use the supported project/runtime configuration route and restart verification. Enable I/O timing temporarily if supported, measuring its overhead. Compare cache misses, I/O latency, SQL/commit latency, CPU and RSS at a fixed 625 load.', 'Measured latency or throughput improves alongside reduced costly reads. An increased cache-hit ratio alone is insufficient; PostgreSQL reads may already hit the OS cache.'),
('5 — WAL and checkpoint behavior', 'If commit or checkpoint waits are material, test max_wal_size=256 MiB first, then independently test wal_buffers=4 MiB (8 MiB only if justified). Verify settings take effect and that the bundled filesystem supports the allocation. Keep fsync, synchronous_commit and full_page_writes on; record WAL generation, checkpoint timing, WAL sync time and recovery implications.', 'Tail latency falls at fixed load, without changing durability or masking client errors. One requested checkpoint per short run is a lead, not proof of checkpoint causality.'),
('6 — SQL and instrumentation checks', 'Capture representative query plans under the same authenticated role and JWT/RLS context, including likes prerequisites and exact-count queries. Compare SQL execution, planning and transaction time rather than relying on cumulative means. Keep existing indexes until a plan identifies a specific gap. Run paired full-metrics versus minimal-metrics/logging trials to quantify observer overhead, retaining gateway counters and resource guards.', 'A specific query, planner behavior, transaction boundary or collector is shown to consume material time. Any optimization preserves API behavior, RLS, auth, returned fields and benchmark work.')]
for title,action,decision in experiments:
    add('<h3>'+title+'</h3><p>'+action+'</p><p class="decision"><strong>Decision signal:</strong> '+decision+'</p>')
add('<p>PostgREST documents a distinct SQL pool and pool-acquisition timeout, but its bundled runtime configuration must be checked before using native settings: '+link('https://docs.postgrest.org/en/stable/references/connection_pool.html','connection pool')+'. PostgreSQL references: '+link('https://www.postgresql.org/docs/17/runtime-config-resource.html','buffer memory')+', '+link('https://www.postgresql.org/docs/17/runtime-config-wal.html','WAL configuration')+', '+link('https://www.postgresql.org/docs/17/runtime-config-query.html','planner cache estimate')+', '+link('https://www.postgresql.org/docs/17/runtime-config-statistics.html','I/O timing')+', '+link('https://www.postgresql.org/docs/17/sql-explain.html','EXPLAIN execution semantics')+'. Proposed sizes are experiment starting points, not tested optimums. Apply one supported change at a time in the benchmark project; do not change unrelated projects.</p>')
add('<h2>7. How to establish improved capacity</h2>')
add('''<p>First repeat the current 500 baseline for 5–10 minutes, watching the rising tail and successful throughput. Repeat 625 with the same settings before and after each candidate fix, ideally in alternating order. Keep a paired baseline with full metrics when testing observer overhead. Once 625 passes, return to 750 and 1,000, then bracket higher points using the same pass criteria. Repeat endpoints and perform a 30-minute soak at the chosen passing point.</p>
<p>A pass requires all seven actions to meet the original p95/p99 and error targets, all configured users to authenticate and finish normally, valid fixture evidence, and no generator or native resource guard failure. A guard failure is an invalid or limited measurement requiring review. Do not improve the published number by increasing client timeouts, adding retries, changing think time, reducing the dataset, removing RLS, weakening password hashing, or disabling durability. Preserve a new configuration/build identity and the original results for each experiment.</p>''')
add('<h2>8. Scope, provenance and uncertainties</h2>')
add('''<p>Environment: installed Supa Desktop 0.14.1, native Apple M1 Max, 10 cores / 64 GiB; no Docker or cgroup CPU/memory cap. k6 shares the Mac, with GOMAXPROCS=9, GOGC=150, GOMEMLIMIT=36 GiB. A second, mostly idle project stayed running. Gateway counters and backend totals include both; PostgreSQL metrics are isolated by benchmark project ID <code>d6e75d8811c143a292f6405173b4b0fb</code>. The generator pressure guard stayed clear, but the existing short-run classifications explicitly leave generator headroom and capacity certification unverified.</p>
<p>Fixture: 15,000 accounts, 150,000 posts, 150,000 likes; 1 KiB bodies; 20-row pages. Action weights: public feed 35%, own feed 15%, read 15%, create 5%, like 17%, unlike 5%, edit 8%. Think time 1–5 seconds; sessions 300–900 seconds. Each run uses 30-second ramp, 60-second warmup and 120-second measurement after untimed setup. Measured users perform fresh normal password logins with paced admission and no retries; no authentication failures occurred. Session token lifetime is 3,600 seconds, so token refresh is not exercised by this short measurement.</p>
<p>Chronological order was 500 → 1,000 → 750 → 625. Logical fixture state was restored between points and after completion; account/post/like counts returned to 15,000/150,000/150,000. This does not reset physical bloat, vacuum progress, caches, WAL/checkpoint history or runtime age. Early point audits recorded cleanup as pending/false before the subsequent restoration completed; the final gateway audits and combined RESULTS.json record verified cleanup. Runs are single observations, and sampled CPU, descriptors and waits can miss short spikes.</p>''')
add('<p>Release-source inspection is pinned to '+link('https://github.com/burggraf/supa-desktop/commit/'+PIN,PIN[:12])+' (release 0.14.1). Installed metadata identifies runtime upstream <code>64a4934099dc15e30e63f11a5a1d04c248c8b49c</code>, data build <code>64a4934-desktop-v3</code>, protocol 3 and armless commit <code>fa8c3f52394f6e263bf63607a25204042a219773</code>. The release profile matches these identifiers; an exact source-to-app binary attestation was not available. Attempts to retrieve the pinned upstream runtime source through the connected GitHub API returned 404; runtime-internal concurrency and the effective SQL-pool setting remain unverified. See '+link('installed-provenance.json','installed metadata')+' and '+source('runtime/profiles/v0.2.0/manifest.json','release runtime profile')+'.</p>')
add('<h2>9. Evidence index</h2><p>The primary conclusion is confirmed at the gateway; the underlying throughput cause remains an investigation target. The report deliberately distinguishes observed failures, source behavior, and proposed experiments.</p>')
add(table(['Users','Primary result','Gateway / resources / bodies','Project DB metrics'],[[t['users'],link('evidence/'+t['directory']+'/measurement-audit.json',t['directory']+' measurement'),link('evidence/'+t['directory']+'/gateway-load-audit.json','gateway-load-audit.json'),link('evidence/'+t['directory']+'/project-metrics-audit.json','project-metrics-audit.json')] for t in TS]))
add('<p>'+link('evidence.json','Derived evidence and input SHA-256 hashes')+' · '+link('analyze.py','Raw-timing replay script')+' · '+link('build-report.py','Report builder')+' · '+link('RESULTS.json','Combined results and cleanup status')+'. Original compressed k6 metrics and raw diagnostic JSONL are retained locally under the ignored results/supa-desktop-native-v0.14.1-20261118/ directory; they are not included in this published snapshot. Published audit copies replace machine-specific paths with relative labels; recorded hashes identify the original captures. No benchmark source, frozen input, app setting or historical audit was overwritten by this investigation.</p>')

css='''*{box-sizing:border-box}html{font-size:16px}body{margin:0;background:#eef2f6;color:#172b43;font-family:system-ui,-apple-system,sans-serif;line-height:1.65}main{max-width:1080px;margin:28px auto;padding:45px 55px;background:white;border:1px solid #d6dce5;border-radius:12px}h1{font-size:38px;line-height:1.15;letter-spacing:-1px;margin:8px 0 22px}h2{font-size:25px;line-height:1.3;margin:38px 0 16px;break-after:avoid}h3{font-size:18px;margin:26px 0 8px;break-after:avoid}p{margin:12px 0;font-size:15px}.eyebrow{font-size:12px;color:#617085;text-transform:uppercase;letter-spacing:1px}.lead{font-size:19px;line-height:1.6}.callout{background:#edf6ff;border-left:4px solid #2789d7;padding:16px 20px;margin:22px 0}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:12px;margin:14px 0}th,td{padding:10px 9px;border-bottom:1px solid #d6dce5;text-align:left;vertical-align:top}th{font-weight:600;color:#4e6178;background:#f5f7fa}a{color:#1567b1;text-decoration-thickness:1px;text-underline-offset:2px}code{font-size:12px;background:#f0f3f7;padding:2px 4px;overflow-wrap:anywhere}.note,.decision{color:#52647b;font-size:13px}.decision{border-left:2px solid #d6dce5;padding-left:12px}svg{break-inside:avoid}footer{border-top:1px solid #d6dce5;margin-top:25px;padding-top:10px;color:#617085;font-size:12px}@media(max-width:700px){main{margin:0;padding:24px 18px;border:0;border-radius:0}h1{font-size:30px}.lead{font-size:17px}}@media print{body{background:white}main{max-width:none;padding:0;margin:0;border:0}a{color:inherit}h1{font-size:30px}h2{font-size:20px}p{font-size:11px}table{font-size:9px}.scroll{overflow:visible}.callout{break-inside:avoid}tr{break-inside:avoid}}'''
